INSERT INTO site_content (key, value) VALUES ('storefront', '{"brand":"Source Connect Global","announcement":"Free delivery islandwide on orders over Rs. 10,000  ✦  China Direct: factory prices, delivered in 10–14 days  ✦  Cash on Delivery available","currency":"Rs.","phone":"+94 77 000 0000","email":"hello@sourceconnectglobal.com","address":"Colombo, Sri Lanka","whatsapp":"94770000000","chinaDays":"10–14","returnDays":7,"welcome":{"on":true,"mode":"session","eyebrow":"Welcome to","subtitle":"Fashion & electronics from around the world, delivered to your door in Sri Lanka.","button":"Enter the Store"},"navLinks":[{"label":"⚡ Flash Sale","link":"#flash","hot":true},{"label":"China Direct","link":"#col/china-direct"},{"label":"Electronics","link":"#col/electronics"},{"label":"Global Imports","link":"#col/global-imports"},{"label":"New Arrivals","link":"#col/new-arrivals"},{"label":"Best Sellers","link":"#col/best-sellers"},{"label":"Under Rs. 2,000","link":"#col/under-2000"},{"label":"All Products","link":"#shop"}],"sections":[{"id":"services","name":"Quick service icons","on":true},{"id":"flash","name":"Flash Sale","on":true},{"id":"countries","name":"Shop by country","on":true,"title":"Shop by Country"},{"id":"categories","name":"Categories grid","on":true},{"id":"banners","name":"Wide promo banners","on":true},{"id":"china","name":"China Direct row","on":true,"title":"China Direct — Factory Prices"},{"id":"electronics","name":"Electronics row","on":true,"title":"Electronics & Gadgets"},{"id":"collections","name":"Collection rows (collections set to “Show on homepage”)","on":true},{"id":"best","name":"Best Sellers row","on":true,"title":"Best Sellers"},{"id":"jfy","name":"Just For You feed","on":true,"title":"Just For You"}],"services":[{"label":"Flash Sale","link":"#flash","icon":"bolt","color":"#d7141a"},{"label":"China Direct","link":"#col/china-direct","icon":"plane","color":"#0b2a6f"},{"label":"New Arrivals","link":"#col/new-arrivals","icon":"tag","color":"#7c3aed"},{"label":"Best Sellers","link":"#col/best-sellers","icon":"star","color":"#f59e0b"},{"label":"Under Rs. 2,000","link":"#col/under-2000","icon":"cash","color":"#0f766e"},{"label":"Free Delivery","link":"#help","icon":"truck","color":"#0284c7"},{"label":"7-Day Returns","link":"#help","icon":"swap","color":"#be185d"},{"label":"Track Order","link":"#track","icon":"pin","color":"#334155"}],"sellerStats":[],"chinaSteps":[{"title":"Sourced","text":"We buy from vetted factories and brands in China, the USA, Australia, the UK, Dubai and Japan."},{"title":"Quality checked","text":"Every batch is inspected before it is packed and shipped."},{"title":"Shipped","text":"Sea freight for bulk, air freight for fast orders. Fully tracked."},{"title":"Cleared in Colombo","text":"We handle customs and duties. No surprise charges for you."},{"title":"Delivered","text":"Islandwide delivery to your door, with Cash on Delivery."}],"faq":[{"q":"How long does delivery take?","a":"It depends on the country: each product page shows the delivery time (for example 10–14 days from China). Items marked “Ships from Colombo” arrive in 2–4 days."},{"q":"Do I pay customs or import duty?","a":"No. Prices include international shipping and customs clearance in Sri Lanka."},{"q":"Can I pay cash on delivery?","a":"Yes, Cash on Delivery is available islandwide. You can also pay by bank transfer."},{"q":"What if the item is wrong or damaged?","a":"Contact us within 7 days of delivery and we will replace it or refund you."},{"q":"How do I track my order?","a":"Use “Track My Order” with your order number and phone number."}]}'::jsonb);
